  "2013.12-1": {
    "sampleAccurate": true,
    "fadeOut": 0.018,
    "endGuard": 0.06,
    "alignment": {
      "status": "user-approved",
      "humanAuditionPassed": false,
      "publicationApproval": {
        "type": "explicit-user-approval",
        "record": "output/audio/timeline-review/summary-n2-2013-12-redo/publication-approval.json",
        "candidateSha256": "bca8ffd1d004a9e8de52f454e52e2aec8d30b91ae1f3e46eaf9d2c1d1605c1bd"
      }
    },
    "question": {
      "src": "../assets/audio/2013.12-1.mp3",
      "start": 5.61,
      "end": 9.48,
      "status": "candidate",
      "humanAuditionPassed": false
    },
    "lines": [
      {
        "src": "../assets/audio/2013.12-1.mp3",
        "start": 11.23,
        "end": 51.14,
        "segments": [
          {
            "src": "../assets/audio/2013.12-1.mp3",
            "start": 11.23,
            "end": 16.02,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "新入生の皆さん、ご家族の皆さん、入学おめでとうございます。",
            "trans": "（各位新生，各位家长，恭喜你们入学。）"
          },
          {
            "src": "../assets/audio/2013.12-1.mp3",
            "start": 16.77,
            "end": 23.31,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "<span class=\"highlight-correct\"><span class=\"opt-tag tag-correct\">④</span>入学式にあたり、私たちの学校について、<span class=\"keyword\" onclick=\"showTooltip(event, '【基本的な考えをお話ししたい】（想谈谈基本理念）：开篇直接点题。明确表示接下来要讲的是学校的核心办学理念。')\">基本的な考えをお話ししたいと思います。</span></span>",
            "trans": "（值此入学典礼之际，我想谈谈关于我们学校的基本理念。）"
          },
          {
            "src": "../assets/audio/2013.12-1.mp3",
            "start": 24.13,
            "end": 30.76,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "本校は、1950年に創立して以来、心の教育を重視してきました。",
            "trans": "（本校自1950年建校以来，一直非常重视心灵教育。）"
          },
          {
            "src": "../assets/audio/2013.12-1.mp3",
            "start": 31.46,
            "end": 35.93,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "学校は<span class=\"highlight-wrong\"><span class=\"opt-tag tag-wrong\">①</span><span class=\"keyword\" onclick=\"showTooltip(event, '明确否定了学校仅仅是提高成绩的地方，可以直接排除选项①。')\">勉強して学力を上げるためだけの場所ではありません。</span></span>",
            "trans": "（学校并不只是为了学习和提高成绩的地方。）"
          },
          {
            "src": "../assets/audio/2013.12-1.mp3",
            "start": 36.67,
            "end": 46.6,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "社会生活の中で必要な礼儀作法を身につけることにより、家族や友人を大切にする心を育てていきたいと思っています。",
            "trans": "（我们希望通过让学生掌握社会生活中必要的礼仪规范，来培养他们珍惜家人和朋友的心。）"
          },
          {
            "src": "../assets/audio/2013.12-1.mp3",
            "start": 47.5,
            "end": 51.14,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "ご家族も、ぜひご協力よろしくお願いします。",
            "trans": "（也请各位家长多多配合。）"
          }
        ]
      },
      {
        "src": "../assets/audio/2013.12-1.mp3",
        "start": 56.89,
        "end": 60.25,
        "status": "candidate",
        "humanAuditionPassed": false
      }
    ]
  },
