  "2015.7-3": {
    "sampleAccurate": true,
    "fadeOut": 0.018,
    "endGuard": 0.06,
    "alignment": {
      "status": "user-approved",
      "humanAuditionPassed": false,
      "publicationApproval": {
        "type": "explicit-user-approval",
        "record": "output/audio/timeline-review/summary-n2-2015-07-redo/publication-approval.json",
        "candidateSha256": "13a9566cb506554e9317a09a4f11e24a173a50cb4f8913d400a7cc5db45fd842"
      }
    },
    "question": {
      "src": "../assets/audio/2015.7-3.mp3",
      "start": 5.7,
      "end": 9.71,
      "status": "candidate",
      "humanAuditionPassed": false
    },
    "lines": [
      {
        "src": "../assets/audio/2015.7-3.mp3",
        "start": 11.41,
        "end": 52.35,
        "segments": [
          {
            "src": "../assets/audio/2015.7-3.mp3",
            "start": 11.41,
            "end": 18.15,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "近年、小学生が理科に興味を持たなくなる子供の理科離れが進んでいます。",
            "trans": "（近年来，小学生对理科失去兴趣，孩子们的“远离理科”现象正在加剧。）"
          },
          {
            "src": "../assets/audio/2015.7-3.mp3",
            "start": 19,
            "end": 27.69,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "<span class=\"highlight-wrong\"><span class=\"opt-tag tag-wrong\">①</span>その対策として、理科の授業を増やしてはどうかという考えがありますが、<span class=\"keyword\" onclick=\"showTooltip(event, '【果たして、それで問題が解決されるでしょうか】（那样真的能解决问题吗？）：用反问句委婉地否定了这种做法，为引出自己真正的主张做铺垫。')\">果たして、それで問題が解決されるでしょうか。</span></span>",
            "trans": "（作为其对策，有观点认为增加理科课时如何，但那样真的能解决问题吗？）"
          },
          {
            "src": "../assets/audio/2015.7-3.mp3",
            "start": 28.5,
            "end": 36.61,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "まずは、<span class=\"highlight-correct\"><span class=\"opt-tag tag-correct\">②</span>深い知識と豊かな経験を備えた<span class=\"keyword\" onclick=\"showTooltip(event, '【～に目を向けるべきだ】（应该把目光放在……上）：直接表达主张的关键句。呼应选项的“致力于培养教师”。')\">現場の指導者を育てることに目を向けるべきだと思います。</span></span>",
            "trans": "（首先，我认为应该把目光放在培养具备渊博知识和丰富经验的一线指导者（教师）上。）"
          },
          {
            "src": "../assets/audio/2015.7-3.mp3",
            "start": 37.55,
            "end": 52.35,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "子供たちに理科を好きになってもらおうと、<span class=\"highlight-wrong\"><span class=\"opt-tag tag-wrong\">③</span>市や町が科学イベントを開催したり</span>、<span class=\"highlight-wrong\"><span class=\"opt-tag tag-wrong\">④</span>学校で興味を引く実験を行ったりしても</span>、その興味が持続するよう、<span class=\"highlight-correct\"><span class=\"opt-tag tag-correct\">②</span><span class=\"keyword\" onclick=\"showTooltip(event, '【～がいなくては意味がない】（如果没有……就没有意义）：再次从反面论证，强调“能引导的人（即教师）”才是最核心的要素。')\">導ける人がいなくては意味がないのです。</span></span>",
            "trans": "（为了让孩子们喜欢上理科，即使市或镇举办科学活动，或者在学校进行引人入胜的实验，如果没有能够引导孩子们保持这种兴趣的人，也是没有意义的。）"
          }
        ]
      },
      {
        "src": "../assets/audio/2015.7-3.mp3",
        "start": 58.12,
        "end": 61.24,
        "status": "candidate",
        "humanAuditionPassed": false
      }
    ]
  },
