            "start": 41.06,
            "end": 46.99,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "<span class=\"highlight-correct\"><span class=\"opt-tag tag-correct\">④</span>自分なりにいろんな工夫ができますし、掃除や洗濯だってそうなんですよ。</span>",
            "trans": "（我可以加入自己的各种巧思，打扫卫生和洗衣服也是一样哦。）"
