            "start": 47.42,
            "end": 52.59,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "<span class=\"highlight-correct\">ちょっとした気づきや発見もあって、<span class=\"highlight-wrong\"><span class=\"opt-tag tag-wrong\">②</span>妻に代わって</span>、張り切ってやってます。</span>",
            "trans": "（会有一些小感悟和新发现，所以我就代替妻子，干劲十足地做着这些。）"
