            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "毎年、機能もソフトも新しくなるので、<span class=\"highlight-wrong\"><span class=\"opt-tag tag-wrong\">②</span>購入するタイミングも難しいんですが</span>、まあ、<span class=\"highlight-correct\"><span class=\"opt-tag tag-correct\">④</span>自分に本当に必要なものは何かよく考えて欲張りすぎず、<span class=\"keyword\" onclick=\"showTooltip(event, '【～をお勧めします】（建议……）：直接表达讲话人核心建议的标志词。这里通过提出具体建议，点明了整段话的主旨，即教大家如何挑选。')\">必要最小限のものに決めるのをお勧めします。</span></span>",
