    "question": {
      "src": "../assets/audio/2015.12-1.mp3",
      "start": 5.34,
      "end": 8.01,
      "status": "candidate",
      "humanAuditionPassed": false
    },
    "lines": [
      {
        "src": "../assets/audio/2015.12-1.mp3",
        "start": 9.76,
        "end": 47.62,
        "segments": [
          {
            "src": "../assets/audio/2015.12-1.mp3",
            "start": 9.76,
            "end": 21.51,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "ええ、近代文学を代表する作家佐藤じゅんですが、<span class=\"highlight-correct\"><span class=\"opt-tag tag-correct\">③</span><span class=\"keyword\" onclick=\"showTooltip(event, '【実は】（其实/实际上）：转折引出与大众认知不同的事实。')\">実は</span>彼は幼い頃から石の採集に夢中で、石先生と呼ばれるほどだったそうです。</span>",
            "trans": "（嗯，代表近代文学的作家佐藤纯，其实他从小时起就热衷于采集石头，甚至到了被称为“石头先生”的程度。）"
          },
          {
            "src": "../assets/audio/2015.12-1.mp3",
            "start": 22.29,
            "end": 25.12,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "<span class=\"highlight-correct\"><span class=\"opt-tag tag-correct\">③</span>これ、<span class=\"keyword\" onclick=\"showTooltip(event, '【ご存知ない方も多いんじゃないでしょうか】（想必有很多人都不知道吧）：直接点明主旨，呼应选项中的“不为人知的一面（知られていない側面）”。')\">ご存知ない方も多いんじゃないでしょうか。</span></span>",
            "trans": "（这一点，想必有很多人都不知道吧。）"
          },
          {
            "src": "../assets/audio/2015.12-1.mp3",
            "start": 25.88,
            "end": 42.43,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "彼は大学で<span class=\"highlight-wrong\"><span class=\"opt-tag tag-wrong\">②</span>農業を専攻し</span>、卒業後故郷に戻って高校の教師になってからも、石の研究は続けていたそうで、彼がふるさとの川で収集した石のコレクションは今でも<span class=\"highlight-wrong\"><span class=\"opt-tag tag-wrong\">①</span>ふるさとの博物館</span>に残されています。",
            "trans": "（他在大学主修农业，毕业后回到故乡成为高中教师之后，似乎也一直在继续着石头的研究，他在故乡的河里收集的石头藏品，至今仍保存在故乡的博物馆里。）"
          },
          {
            "src": "../assets/audio/2015.12-1.mp3",
            "start": 43.04,
            "end": 47.62,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "<span class=\"highlight-wrong\"><span class=\"opt-tag tag-wrong\">④</span>彼の作品を読むと</span>、石の名前なんかがよく登場するんですよ。",
            "trans": "（读他的作品时，经常会出现石头的名字哦。）"
          }
        ]
      },
      {
        "src": "../assets/audio/2015.12-1.mp3",
        "start": 53.38,
        "end": 56.71,
        "status": "candidate",
        "humanAuditionPassed": false
      }
    ]
