            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "近年職場での<span class=\"highlight-wrong\"><span class=\"opt-tag tag-wrong\">③</span>人間関係や長時間労働によってストレスを抱える人が増えています</span>が、無理を続けたために、対処が遅れ、長期休養を取らざるをえなくなってしまうケースが多く見られます。",
            "trans": "（近年来，因职场人际关系和长时间劳动而承受压力的人越来越多，由于一直勉强自己，导致应对迟缓，不得不长期休养的情况屡见不鲜。）"
