            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "<span class=\"highlight-correct\"><span class=\"opt-tag tag-correct\">②</span><span class=\"keyword\" onclick=\"showTooltip(event, '【最初の一歩が早ければ～防ぐことが出来る】（如果迈出的第一步够早，就能防止恶化）：点明了“尽早（早期）”采取应对行动的核心价值。')\">最初の一歩が早ければ、状態が深刻化するのを防ぐことが出来るのですが</span></span>、<span class=\"highlight-wrong\"><span class=\"opt-tag tag-wrong\">④</span>真面目な人ほど一人で悩みを抱えてしまい</span>、カウンセラーのところにやってくる頃には症状が進んでいることも稀ではありません。",
            "trans": "（如果迈出的第一步够早，是能够防止状况恶化的，但越是认真的人越容易一个人把烦恼憋在心里，来到咨询师这里时症状已经恶化的情况也不少见。）"
