            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "カウンセラーの存在が広く知られるようになった今日でも、<span class=\"highlight-correct\"><span class=\"opt-tag tag-correct\">②</span><span class=\"keyword\" onclick=\"showTooltip(event, '【相談に来るのに消極的な人が多いのは残念です】（对前来咨询持消极态度的人很多，这很遗憾）：通过表达遗憾，反向呼吁大家应该积极、尽早地来接受心理咨询。')\">相談に来るのに消極的な人が多いのは残念です。</span></span>",
            "trans": "（即使在咨询师的存在已被广泛知晓的今天，对于前来咨询仍持消极态度的人还有很多，这非常遗憾。）"
