            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "皆さんは仕事でよい結果を残せるタイプですか、それともなかなかうまくいかないタイプですか。",
            "trans": "（大家是在工作中能留下好结果的类型，还是怎么也做不好的类型呢？）"
