            "end": 40.27,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "一方、虫の目は近くで対象をじっくり見つめるため、対象物の微妙な動きや変化をしることができます。",
            "trans": "（另一方面，虫的眼睛在近处仔细注视对象，因此能了解对象物微妙的动作和变化。）"
