            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "広い視野で物事を捉え考えることと、物事を細かく観察し分析すること。<span class=\"highlight-correct\"><span class=\"opt-tag tag-correct\">③</span><span class=\"keyword\" onclick=\"showTooltip(event, '【職場でもこの両方の目を～結果が得られるでしょう】（在职场中如果也能时刻意识到这两种眼光，就能获得更好的结果）：结尾明确点明了主旨，呼应了“对工作有用的看待事物的方法”。')\">職場でもこの両方の目を常に意識していればより良い結果が得られるでしょう。</span></span>",
            "trans": "（以广阔的视野来捕捉和思考事物，以及仔细观察和分析事物。在职场中，如果也能时刻意识到这两种眼光，就能获得更好的结果吧。）"
