            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "<span class=\"highlight-correct\"><span class=\"opt-tag tag-correct\">①</span><span class=\"keyword\" onclick=\"showTooltip(event, '【それは、～ためです】（那是由于……的原因）：引出核心因果关系。那是由于这部电影在此高中取景拍摄所致，是解释现象发生的直接依据。')\">それは、この高校で映画『青春ストーリー』が撮影されたためです。</span></span>",
            "trans": "（那是由于这部电影《青春故事》是在这里拍摄的。）"
