            "start": 34.98,
            "end": 46.37,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "<span class=\"highlight-correct\"><span class=\"opt-tag tag-correct\">①</span>この映画に出演していた俳優青木たくやさんが去年別の映画で世界的な映画賞を取ったことで、<span class=\"keyword\" onclick=\"showTooltip(event, '【海外でもこの映画が注目されるようになった】（海外也开始关注起这部电影）：指出了触发去年以来游客激增的外部国际因素。')\">海外でもこの映画が注目されるようになった</span>んだそうです。</span>",
            "trans": "（据说出演这部电影的演员青木拓也去年凭借另一部电影获得了世界级的电影奖项，使得这部电影在海外也受到了关注。）"
