        "segments": [
          {
            "src": "../assets/audio/2018.7-5.mp3",
            "start": 10.2,
            "end": 20.45,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "昨年度の調査によると、わが川中町ではだれも住んでいない空家がこの十年で二倍に増えていることが明らかになりました。",
            "trans": "（根据去年的调查显示，在我们川中町，无人居住的空置房在过去十年中增加了一倍。）"
          },
          {
            "src": "../assets/audio/2018.7-5.mp3",
            "start": 21.12,
            "end": 25.79,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "<span class=\"highlight-wrong\"><span class=\"opt-tag tag-wrong\">②</span>空家の増加は地域の防犯上、深刻な問題です。</span>",
            "trans": "（空置房的增加在地区防范上是一个严重的问题。）"
          },
          {
            "src": "../assets/audio/2018.7-5.mp3",
            "start": 26.28,
            "end": 32.14,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "火災の発見が遅れたり、建物が古くなって崩れたりする危険もあります。",
            "trans": "（还存在火灾发现延迟，或者建筑物变旧倒塌的危险。）"
          },
          {
            "src": "../assets/audio/2018.7-5.mp3",
            "start": 32.82,
            "end": 41.64,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "<span class=\"highlight-wrong\"><span class=\"opt-tag tag-wrong\">②</span>そうした空家は早急に<span class=\"keyword\" onclick=\"showTooltip(event, '【取り壊すべきだという意見が出ていますが】（虽然出现了应该尽早拆除的意见）：这只是议员列举的目前社会上存在的方案之一，随后他就用转折词引出了自己的不同主张。')\">取り壊すべきだという意見が出ていますが</span>、</span><span class=\"highlight-correct\"><span class=\"opt-tag tag-correct\">③</span><span class=\"keyword\" onclick=\"showTooltip(event, '【再生させる道を探るほうがいい】（寻找再利用/重生的道路比较好）：这是议员的核心主张，即不主张简单粗暴的拆除，而是主张进行二次开发利用。')\">再生させる道を探るほうがいいのではないでしょうか。</span></span>",
            "trans": "（虽然有人提出这类空置房应该尽早拆除的意见，但难道不是寻找一条重生的道路更好吗？）"
          },
          {
            "src": "../assets/audio/2018.7-5.mp3",
            "start": 42.07,
            "end": 53.47,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "全国の例を調べてみますと自治体が空家を管理し、商業施設として再生させているところもあり、人を呼び込むことにつながっている例もあります。",
            "trans": "（查阅全国的例子可以发现，有的地方由地方政府管理空置房，将其作为商业设施重新利用，从而起到了吸引人流的作用。）"
          }
        ]
