  "2019.7-3": {
    "sampleAccurate": true,
    "fadeOut": 0.018,
    "endGuard": 0.06,
    "alignment": {
      "status": "user-approved",
      "humanAuditionPassed": false,
      "publicationApproval": {
        "type": "explicit-user-approval",
        "record": "output/audio/timeline-review/summary-n2-2019-07-redo/publication-approval.json",
        "candidateSha256": "7012839f551cf77bc9ce6265718b36d130e89c1dcb1fe3f9c2dab2fdb46afcae"
      }
    },
    "question": {
      "src": "../assets/audio/2019.7-3.mp3",
      "start": 5.62,
      "end": 8.63,
      "status": "candidate",
      "humanAuditionPassed": false
    },
    "lines": [
      {
        "src": "../assets/audio/2019.7-3.mp3",
        "start": 10.36,
        "end": 46.7,
        "segments": [
          {
            "src": "../assets/audio/2019.7-3.mp3",
            "start": 10.36,
            "end": 16.1,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "料理を作ったら、食べた人に美味しいと言ってほしいとみんな思いますよね。",
            "trans": "（大家都希望做好了菜之后，吃的人能说好吃对吧。）"
          },
          {
            "src": "../assets/audio/2019.7-3.mp3",
            "start": 16.4,
            "end": 26.3,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "ところが、好みは人それぞれ、<span class=\"highlight-correct\"><span class=\"opt-tag tag-correct\">④</span><span class=\"keyword\" onclick=\"showTooltip(event, '【好みを形成するものの一つは～家庭料理の味です】（形成这种口味偏好的因素之一是……家庭料理的味道）：点明了影响口味的第一个要素是童年习惯的家庭味道。')\">その好みを形成するものの一つは子供の頃から毎日食べていた家庭料理の味です。</span></span>",
            "trans": "（然而，口味因人而异，形成这种口味偏好的因素之一，是从小每天吃的家庭料理的味道。）"
          },
          {
            "src": "../assets/audio/2019.7-3.mp3",
            "start": 26.81,
            "end": 36.07,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "家庭だけでなく、学生時代によく通っていた食堂などの慣れ親しんだ味を美味しいと感じることが多いと言われています。",
            "trans": "（不仅是家庭，据说人们也常会觉得学生时代常去的食堂等那种习惯亲近的味道很好吃。）"
          },
          {
            "src": "../assets/audio/2019.7-3.mp3",
            "start": 36.39,
            "end": 46.7,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "<span class=\"highlight-correct\"><span class=\"opt-tag tag-correct\">④</span>ほかにも暑い地域では、汗をかいて体温を下げる効果のある辛い料理が好まれるといった<span class=\"keyword\" onclick=\"showTooltip(event, '【気候によるものなどもあります】（也有受气候影响的因素等）：引出影响口味的第二个要素，即环境气候。结合前文，全段都在探讨到底是什么决定了人的口味。')\">気候によるものなどもあります。</span></span>",
            "trans": "（除此之外，在炎热的地区，人们喜欢能出汗降温的辣味料理，也有这种受气候影响的因素等。）"
          }
        ]
      },
      {
        "src": "../assets/audio/2019.7-3.mp3",
        "start": 52.24,
        "end": 56.06,
        "status": "candidate",
        "humanAuditionPassed": false
      }
    ]
  },
