  "2019.12-2": {
    "sampleAccurate": true,
    "fadeOut": 0.018,
    "endGuard": 0.06,
    "alignment": {
      "status": "user-approved",
      "humanAuditionPassed": false,
      "publicationApproval": {
        "type": "explicit-user-approval",
        "record": "output/audio/timeline-review/summary-n2-2019-12-redo/publication-approval.json",
        "candidateSha256": "a8607ced3f006da50d069ad2a9fb2fa0fc054f8bcdfa1d72478e676d7947142c"
      }
    },
    "question": {
      "src": "../assets/audio/2019.12-2.mp3",
      "start": 5.65,
      "end": 8.56,
      "status": "candidate",
      "humanAuditionPassed": false
    },
    "lines": [
      {
        "src": "../assets/audio/2019.12-2.mp3",
        "start": 10.3,
        "end": 51.19,
        "segments": [
          {
            "src": "../assets/audio/2019.12-2.mp3",
            "start": 10.3,
            "end": 20.12,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "ある高齢者介護施設では、わざと施設内に階段や段差を設置しているそうです。",
            "trans": "（据说某家高龄者护理设施里，故意在设施内设置了楼梯和台阶。）"
          },
          {
            "src": "../assets/audio/2019.12-2.mp3",
            "start": 20.24,
            "end": 28.47,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "えっと思われるかもしれませんが、<span class=\"highlight-correct\"><span class=\"opt-tag tag-correct\">②</span><span class=\"keyword\" onclick=\"showTooltip(event, '【あえて不便にすることで、体力や体の機能の低下を防ごうとするものなんです】（通过故意制造不便，来防止体力和身体机能的衰退）：明确指出了制造不便所带来的正面效果。')\">あえて不便にすることで、体力や体の機能の低下を防ごうとするものなんです。</span></span>",
            "trans": "（大家可能会觉得惊讶，但这是为了故意制造不便，从而防止体力和身体机能的衰退。）"
          },
          {
            "src": "../assets/audio/2019.12-2.mp3",
            "start": 29.44,
            "end": 39.97,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "<span class=\"highlight-wrong\"><span class=\"opt-tag tag-wrong\">③</span>パソコンの普及で漢字が書けなくなったなんてよく聞きますが</span>、昔は何でも手書きで手間はかかるけど、<span class=\"highlight-correct\"><span class=\"opt-tag tag-correct\">②</span>おかげで<span class=\"keyword\" onclick=\"showTooltip(event, '【漢字を忘れずに済んだわけですよね】（多亏了那样才没有忘记汉字呢）：同样指出了不方便（手写）带来的好处。')\">漢字を忘れずに済んだわけですよね。</span></span>",
            "trans": "（常听说因为电脑的普及导致人们不会写汉字了，过去什么都用手写虽然费事，但也多亏了那样才没有忘记汉字呢。）"
          },
          {
            "src": "../assets/audio/2019.12-2.mp3",
            "start": 41.23,
            "end": 51.19,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "そういえば、先日うちの掃除機が壊れて、家中ほうきで掃いたんですけど、<span class=\"highlight-correct\"><span class=\"opt-tag tag-correct\">②</span>日ごろの運動不足が解消された気が……<span class=\"keyword\" onclick=\"showTooltip(event, '【これも同じことかなあ】（这也是同样的道理吧）：将日常的经历与前文联系起来，总结得出“不方便也有好处”的核心观点。')\">これも同じことかなあ。</span></span>",
            "trans": "（说起来，前几天我家的吸尘器坏了，我用扫帚扫了全家，感觉消除了平时的运动不足……这也是同样的道理吧。）"
          }
        ]
      },
      {
        "src": "../assets/audio/2019.12-2.mp3",
        "start": 55.14,
        "end": 62.02,
        "status": "candidate",
        "humanAuditionPassed": false
      }
    ]
  },
