  "2019.12-5": {
    "sampleAccurate": true,
    "fadeOut": 0.018,
    "endGuard": 0.06,
    "alignment": {
      "status": "user-approved",
      "humanAuditionPassed": false,
      "publicationApproval": {
        "type": "explicit-user-approval",
        "record": "output/audio/timeline-review/summary-n2-2019-12-redo/publication-approval.json",
        "candidateSha256": "a8607ced3f006da50d069ad2a9fb2fa0fc054f8bcdfa1d72478e676d7947142c"
      }
    },
    "question": {
      "src": "../assets/audio/2019.12-5.mp3",
      "start": 5.5,
      "end": 9.21,
      "status": "candidate",
      "humanAuditionPassed": false
    },
    "lines": [
      {
        "src": "../assets/audio/2019.12-5.mp3",
        "start": 10.98,
        "end": 51.07,
        "segments": [
          {
            "src": "../assets/audio/2019.12-5.mp3",
            "start": 10.98,
            "end": 20.6,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "日本は昔から、木の文化と言われていますが、近年では、<span class=\"highlight-wrong\"><span class=\"opt-tag tag-wrong\">②</span>木造住宅の建築に、外国の木材が多く使われています。</span>",
            "trans": "（日本自古以来就被称为木之文化，但近年来，在木造住宅的建筑中，大量使用了外国木材。）"
          },
          {
            "src": "../assets/audio/2019.12-5.mp3",
            "start": 21.2,
            "end": 26.81,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "価格が安く、種類も豊富な輸入木材に、国産が押されているわけです。",
            "trans": "（价格便宜、种类丰富的进口木材，挤压了国产木材的市场。）"
          },
          {
            "src": "../assets/audio/2019.12-5.mp3",
            "start": 27.19,
            "end": 42.34,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "<span class=\"highlight-correct\"><span class=\"opt-tag tag-correct\">③</span>しかし、<span class=\"keyword\" onclick=\"showTooltip(event, '【雨が多い日本で育った木は～長く使うことができるんです】（在多雨的日本长大的树木……能够长久使用）：使用转折词「しかし」引出核心观点，详细列举了日本国产木材适应当地气候、不易腐烂变形等优点。')\">雨が多い日本で育った木は、梅雨の時期や高温で湿度の高い夏でも腐らず、冬の乾燥でも変形しないなど、日本の気候に非常によく合っていて、長く使うことができるんです。</span></span>",
            "trans": "（但是，在多雨的日本长大的树木，在梅雨季节和高温高湿的夏天也不会腐烂，在冬天的干燥中也不会变形等，非常适合日本的气候，能够长久使用。）"
          },
          {
            "src": "../assets/audio/2019.12-5.mp3",
            "start": 43.23,
            "end": 48.33,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "百年前の木造の家だって、手入れすればまだ住めるほどです。",
            "trans": "（即便是百年前的木造房屋，只要加以保养就还能居住。）"
          },
          {
            "src": "../assets/audio/2019.12-5.mp3",
            "start": 48.84,
            "end": 51.07,
            "status": "candidate",
            "humanAuditionPassed": false,
            "html": "<span class=\"highlight-correct\"><span class=\"opt-tag tag-correct\">③</span>もう一度、<span class=\"keyword\" onclick=\"showTooltip(event, '【見直してもらいたいですね】（希望能被重新审视）：在结尾呼吁大家重新认识国产木材的价值，呼应了主旨。')\">見直してもらいたいですね。</span></span>",
            "trans": "（希望能被大家重新审视呢。）"
          }
        ]
      },
      {
        "src": "../assets/audio/2019.12-5.mp3",
        "start": 52.98,
        "end": 60.15,
        "status": "candidate",
        "humanAuditionPassed": false
      }
    ]
  },
