            "html": "<span class=\"highlight-wrong\"><span class=\"opt-tag tag-wrong\">①</span>現在、海外の25カ国で放送されていて、</span>原作のマンガも<span class=\"highlight-wrong\"><span class=\"opt-tag tag-wrong\">②</span>五つの言語に翻訳されています。</span>",
