            "html": "<span class=\"highlight-correct\"><span class=\"opt-tag tag-correct\">④</span><span class=\"keyword\" onclick=\"showTooltip(event, '【日本にとどまらず、世界中でファンを獲得しているようです】（不仅限于日本，看来正在全世界获得粉丝）：结尾的总结句，再次呼应了“在世界范围内人气提升”的主旨。')\">日本にとどまらず、世界中でファンを獲得しているようです。</span></span>",
